head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDFIS00600_P6.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 * 재무유형 조회
 */
scwin.fn_GetDtsAccntPttn = function() {
    dts_AccntPttn.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.accntPttn" + "&outputMessageId=FIS_ACNTCLS_DT" + "&param01=" + $c.stf.getObjectValue(cmb_ACNTG_BAS_TYP) + "&param02=" + $c.stf.getObjectValue(cmb_IND_PTTN);
    dts_AccntPttn.DataID = encodeURI(url);
    dts_AccntPttn.Reset();
};


/**
 * 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    dts_Acnt.removeAll();
    dts_SelectAcnt.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.modifyAccntCd" + "&outputMessageId=FIS_MODIFY_ACNT_LIST" + "&param01=" + $c.stf.getObjectValue(cmb_ACNTG_BAS_TYP) + "&param02=" + $c.stf.getObjectValue(cmb_IND_PTTN) + "&param03=" + $c.stf.getObjectValue(cmb_INDVDL_CONN_TP) + "&param04=" + "&param05=" + $c.stf.getObjectValue(cmb_ACCNT_PTTN);
    dts_Acnt.DataID = encodeURI(url);
    dts_Acnt.Reset();
    dts_SelectAcnt.DataID = encodeURI(url);
    dts_SelectAcnt.Reset();
};
scwin.dts_Acnt_OnLoadError = function() {
    $c.stf.alert_error(dts_Acnt);
};
scwin.dts_Acnt_OnLoadCompleted = function(rowcount) {
    if (dts_Acnt.errorMsg) {
        $c.win.alert(dts_Acnt.errorMsg);
    }
    $c.cm.CloseWin(rowcount, panel_Top);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_GetDtsAccntPttn();
    scwin.fn_Search();
};
scwin.img_Close_onclick = async function() {
    // 닫기버튼 클릭
    await $c.frame.CloseFrame();
};
scwin.dts_Year_OnLoadCompleted = function(rowcount) {
    if (dts_Year.errorMsg) {
        $c.win.alert(dts_Year.errorMsg);
    }
};
scwin.cmb_ACCNT_PTTN_OnSelChange = function() {
    scwin.fn_Search();
};
scwin.cmb_FISCAL_TYP_OnSelChange = function() {
    scwin.fn_Search();
};
scwin.cmb_IND_PTTN_OnSelChange = function() {
    scwin.fn_Search();
};
scwin.cmb_INDVDL_CONN_TP_OnSelChange = function() {
    scwin.fn_Search();
};
scwin.cmb_ACNTG_BAS_TYP_OnSelChange = function() {
    scwin.fn_Search();
};
scwin.trv_Acnt_OnContextMenu = function(x, y, row) {
    trv_Acnt.TrackPopupMenu(x, y);
};
scwin.trv_Acnt_OnCommand = function(code, text) {
    var nRow = dts_Acnt.getRowPosition();
    var ACCNT_CD = dts_Acnt.getCellData(nRow, "ACCNT_CD");
    var ACNTG_BAS_TYP = dts_Acnt.getCellData(nRow, "ACNTG_BAS_TYP");
    var IND_PTTN = dts_Acnt.getCellData(nRow, "IND_PTTN");
    var ACCNT_PTTN = dts_Acnt.getCellData(nRow, "ACCNT_PTTN");
    var INDVDL_CONN_TP = $c.stf.getObjectValue(cmb_INDVDL_CONN_TP);
    var S_LV = dts_Acnt.getCellData(nRow, "LV");

    // alert( trv_SelectedAcnt.ItemText );
    // ACCNT_CD || '^' || TRIM(FSS_ACCNT_CD) || '^' || ID_VRF_ORD || '^'

    var array = trv_SelectedAcnt.ItemText.split("^");
    T_ACCNT_CD = array[0];
    T_FSS_ACCNT_LV = array[1];
    T_ORD = array[2];

    // 단건이동
    if (code == "1") {
        if (trv_SelectedAcnt.getSelectedNode().label == "") {
            $c.win.alert("이동할 곳을 지정해 주세요");
            return;
        }
        //dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_ListUpdate.insertRow();
        dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
        dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
        dts_ListUpdate.setCellData(1, "S_LV", S_LV);
        dts_ListUpdate.setCellData(1, "T_ACCNT_CD", T_ACCNT_CD);
        dts_ListUpdate.setCellData(1, "T_ORD", /*ORG SRC: dts_ListUpdate.setNameValue(1, "T_ORD", dts_ListUpdate.NameValue(1, "T_ORD") = );*/ X = X);
        dts_ListUpdate.setCellData(1, "T_LV", T_FSS_ACCNT_LV);
        trs_save.Action = "/ConditionSrchAction.do?method=updateAccntCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_ListUpdate)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }

    // 하위포함이동
    if (code == "2") {
        if (trv_SelectedAcnt.getSelectedNode().label == "") {
            $c.win.alert("이동할 곳을 지정해 주세요");
            return;
        }
        //dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_ListUpdate.insertRow();
        dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
        dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
        dts_ListUpdate.setCellData(1, "S_LV", S_LV);
        dts_ListUpdate.setCellData(1, "T_ACCNT_CD", T_ACCNT_CD);
        dts_ListUpdate.setCellData(1, "T_ORD", /*ORG SRC: dts_ListUpdate.setNameValue(1, "T_ORD", dts_ListUpdate.NameValue(1, "T_ORD") = );*/ X = X);
        dts_ListUpdate.setCellData(1, "T_LV", T_FSS_ACCNT_LV);
        trs_save.Action = "/ConditionSrchAction.do?method=updateAccntCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_ListUpdate)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }

    // LV 1증가
    if (code == "3") {
        var plus = "1";
        //dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ListUpdate.insertRow();
        dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
        dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
        dts_ListUpdate.setCellData(1, "S_LV", plus);
        trs_save.Action = "/ConditionSrchAction.do?method=updateAccntCdLv" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_ListUpdate)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }

    // LV 1감소
    if (code == "4") {
        var minus = "-1";
        //dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ListUpdate.insertRow();
        dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
        dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
        dts_ListUpdate.setCellData(1, "S_LV", minus);
        trs_save.Action = "/ConditionSrchAction.do?method=updateAccntCdLv" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_ListUpdate)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
};
scwin.trs_save_OnSuccess = function() {
    scwin.fn_Search();
};
scwin.trs_save_OnFail = function() {
    $c.win.alert('trs_save.OnFail()');
};
